import {NgModule} from '@angular/core';
import {RouterModule, Routes} from '@angular/router';
import {BlogpostPublicComponent} from "./domains/blogposts/blogpost-public.component";
import {BlogpostDetailComponent} from "./domains/blogpost-detail/blogpost-detail.component";

const routes: Routes = [
  {path: ':slug/posts', component: BlogpostPublicComponent},
  {path: ':slug/categories/:categorySlug/posts', component: BlogpostPublicComponent},
  {path: ':slug/hashtags/:hashtag/posts', component: BlogpostPublicComponent},
  {path: ':slug/posts/:postSlug', component: BlogpostDetailComponent},
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class BlogRoute {
}
