import {Component} from '@angular/core';
import {IBlogPostDetail} from "../../../dash/domains/blog/blogposts/models/blogpost.model";
import {EventBusService} from "../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../base/services/subscription-container.service";
import {NotifierService} from "../../../../services/notifier/notifier.service";
import {
  BlogPostListComponent
} from "../../../dash/domains/blog/blogposts/components/blogpost-list/blogpost-list.component";
import {BaseComponent} from "../../../../base/components/base.component";
import {EventKey} from "../../../../services/eventbus/event.key";
import {MetaData} from "ng-event-bus/lib/meta-data";
import {BlogPostService} from "../../../dash/domains/blog/blogposts/services/blogpost.service";
import {Meta, Title} from "@angular/platform-browser";

@Component({
  selector: 'app-blogpost-detail',
  templateUrl: './blogpost-detail.component.html',
  styleUrls: ['./blogpost-detail.component.scss']
})
export class BlogpostDetailComponent extends BaseComponent {

  blogSlug: string | null = null
  postSlug: string | null = null

  blogPost: IBlogPostDetail | null = null

  protected componentName(): string {
    return BlogPostListComponent.name;
  }

  constructor(
    eventBus: EventBusService,
    router: Router,
    subContainer: SubscriptionContainerService,
    private activatedRoute: ActivatedRoute,
    private notifier: NotifierService,
    private blogpostService: BlogPostService,
    private seoTitle: Title,
    private seoMeta: Meta
  ) {
    super(eventBus, router, subContainer)
  }

  ngOnInit(): void {
    this.activatedRoute.paramMap.subscribe(pathVariables => {

      this.blogSlug = pathVariables.get('slug');
      this.postSlug = pathVariables.get('postSlug');

      this.fetchBlogPosts(this.blogSlug!!, this.postSlug!!, post=>{
        this.blogPost = post
        this.resolveSeo(post)
      })
    });
  }

  private fetchBlogPosts(blogSlug: string, postSlug: string, then: (result: IBlogPostDetail)=> void) {
    this.loading = true
    const key = this.componentKey(EventKey.BLOGPOSTS.GET_DETAILS(postSlug))
    this.blogpostService.fetchSinglePublic(key, blogSlug, postSlug)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        then(meta.data)
        this.loading = false
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.error.message)
    })
  }

  getCategoryNames(post: IBlogPostDetail | null): string {
    if (post == null || post.categories.length === 0) return "Uncategorized"
    return post.categories.map((c) => {
      return c.name
    }).join(", ");
  }

  private resolveSeo(post: IBlogPostDetail | null) {
    if (post == null){
      console.log("Post null")
      return
    }

    super.initSeoItems(
      this.seoTitle,
      this.seoMeta,
      post.title,
      post.content.content,
      [post.content.hashtags.join(",")],
      null,
      null,
      post.featured_image,
      this.getPermalink()
    )
  }
}
