import {Component} from '@angular/core';
import {BaseListComponentV4} from "../../../../base/components/base-list-v4.component";
import {IBlogPost, IBlogPostDetail} from "../../../dash/domains/blog/blogposts/models/blogpost.model";
import {
  BlogPostConfig,
  defaultBlogPostConfig,
  selfEndpoints,
  selfRoutes
} from "../../../dash/domains/blog/blogposts/models/config.model";
import {
  BasicFilterData,
  defaultFilterData,
  parseFilterData,
  toParams
} from "../../../common/modules/utility/components/basic-filter/basic-filter.model";
import {defaultPage, IPage} from "../../../../base/models/IPage";
import {EventBusService} from "../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../base/services/subscription-container.service";
import {AuthService} from "../../../common/modules/auth/services/auth.service";
import {DialogService} from "../../../common/modules/utility/components/popup/dialog.service";
import {BlogPostService} from "../../../dash/domains/blog/blogposts/services/blogpost.service";
import {NotifierService} from "../../../../services/notifier/notifier.service";
import {BreadcrumbItem} from "../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {IParams} from "../../../../base/endpoints/iparams";
import {EventKey} from "../../../../services/eventbus/event.key";
import {MetaData} from "ng-event-bus/lib/meta-data";
import {BaseConfigV2} from "../../../../base/models/baseConfig";
import {ComponentType} from "@angular/cdk/overlay";
import {BaseUpsertComponentV3} from "../../../../base/components/base-upsert-v3.component";
import {
  BlogPostListComponent
} from "../../../dash/domains/blog/blogposts/components/blogpost-list/blogpost-list.component";
import {DashEndpoint} from "../../../dash/dash.endpoint";
import {PostCategoryService} from "../../../dash/domains/blog/postcategories/services/postcategory.service";
import {IPostCategory} from "../../../dash/domains/blog/postcategories/models/postcategory.model";
import {TopHashtag} from "../../models/top-hashtag.model";

@Component({
  selector: 'app-blogpost-public',
  templateUrl: './blogpost-public.component.html',
  styleUrls: ['./blogpost-public.component.scss']
})
export class BlogpostPublicComponent extends BaseListComponentV4<IBlogPost, IBlogPostDetail> {
  config: BlogPostConfig = defaultBlogPostConfig
  filterData: BasicFilterData = defaultFilterData

  blogPosts: IPage<IBlogPost> = defaultPage
  topPosts: IPage<IBlogPost> = defaultPage
  categories: IPage<IPostCategory> = defaultPage
  topHashtags: TopHashtag[] = []

  blogSlug: string | null = null
  categorySlug: string | null = null
  hashtag: string | null = null

  protected componentName(): string {
    return BlogPostListComponent.name;
  }

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              authService: AuthService,
              dialog: DialogService<IBlogPostDetail>,
              private activatedRoute: ActivatedRoute,
              private blogPostService: BlogPostService,
              private postCategoryService: PostCategoryService,
              private notifier: NotifierService,
  ) {
    super(eventBus, router, subContainer, dialog)
    if (authService.isAdmin()) {
      this.config.showUserFilter = true
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }
  }

  initialize(): void {
    this.activatedRoute.paramMap.subscribe(pathVariables => {

      this.activatedRoute.queryParams.subscribe(params => {
        this.filterData = parseFilterData(params)
        this.blogSlug = pathVariables.get('slug');
        this.categorySlug = pathVariables.get('categorySlug');
        this.hashtag = pathVariables.get('hashtag');

        let p = {
          q: this.filterData.query,
          from_date: this.filterData.fromDate,
          to_date: this.filterData.toDate,
          page: this.filterData.page,
          size: this.filterData.size,
          sort_by: this.filterData.sort_by,
          sort_direction: this.filterData.sort_direction
        }

        if (this.categorySlug != null) {
          this.fetchBlogPostsForCategory(this.blogSlug!!, this.categorySlug, p)
        } else if (this.hashtag != null) {
          this.fetchBlogPostsForHashtag(this.blogSlug!!, this.hashtag, p)
        } else {
          this.fetchBlogPosts(this.blogSlug!!, p, result => {
            this.blogPosts = result
          })
        }

        // Fetch Top Blogposts
        this.fetchBlogPosts(this.blogSlug!!, {
          ...p,
          q: '',
          size: 5,
          sort_by: 'viewCount',
          sort_direction: 'DESC'
        }, result => {
          this.topPosts = result
        })

        this.fetchCategories(this.blogSlug!!, {
          ...p,
          sort_by: 'id',
          sort_direction: 'ASC'
        })

        this.fetchHashtags(this.blogSlug!!)

      });
    });
  }

  findCategoryName(slug: string): string {
    return this.categories.content.find((c) => {
      return c.slug == slug
    })?.name ?? "Uncategorized"
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return []
  }

  private fetchBlogPosts(blogSlug: string, params: IParams, onResult: (result: IPage<IBlogPost>) => void) {
    this.loading = true
    const key = this.componentKey(EventKey.BLOGPOSTS.SEARCH(params))
    this.blogPostService.search(key, DashEndpoint.BLOGPOSTS.BLOGPOST_ENDPOINT_PUBLIC_ALL(blogSlug), params)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        onResult(meta.data)
        this.loading = false
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.error.message)
    })
  }

  private fetchBlogPostsForCategory(blogSlug: string, categorySlug: string, params: IParams) {
    this.loading = true
    const key = this.componentKey(EventKey.BLOGPOSTS.SEARCH_BY_CATEGORY(categorySlug, params))
    this.blogPostService.search(key, DashEndpoint.BLOGPOSTS.BLOGPOST_BY_CATEGORY(blogSlug, categorySlug), params)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        this.blogPosts = meta.data
        this.loading = false
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.error.message)
    })
  }

  private fetchBlogPostsForHashtag(blogSlug: string, hashtag: string, params: IParams) {
    this.loading = true
    const key = this.componentKey(EventKey.BLOGPOSTS.SEARCH_BY_HASHTAG(hashtag, params))
    this.blogPostService.search(key, DashEndpoint.BLOGPOSTS.BLOGPOST_BY_HASHTAG(blogSlug, hashtag), params)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        this.blogPosts = meta.data
        this.loading = false
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.error.message)
    })
  }


  private fetchCategories(blogSlug: string, params: IParams) {
    this.loading = true
    const key = this.componentKey(EventKey.POST_CATEGORIES.SEARCH_PUBLIC(params))
    this.postCategoryService.search(key, DashEndpoint.POST_CATEGORIES.POST_CATEGORY_ENDPOINT_PUBLIC(blogSlug), params)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        this.categories = meta.data
        this.loading = false
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.error.message)
    })
  }

  private fetchHashtags(blogSlug: string) {
    this.loading = true
    const key = this.componentKey(EventKey.BLOGPOSTS.GET_TOP_HASHTAGS(blogSlug))
    this.postCategoryService.getTopHashtags(key, blogSlug)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        this.topHashtags = meta.data
        this.loading = false
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.error.message)
    })
  }

  onDeleted(deleted: Boolean) {
    if (deleted) {
      this.notifier.success("Success", "BlogPost is deleted")
      this.ngOnInit()
    }
  }

  override getConfig(): BaseConfigV2 {
    return this.config
  }

  override getRoutes(): { create: string, update: (id: number) => string, params: IParams } | null {
    return {
      create: selfRoutes.create,
      update: (id: number) => selfRoutes.update(id),
      params: toParams(this.filterData)
    }
  }

  getUpsertComponent(): ComponentType<BaseUpsertComponentV3<IBlogPostDetail>> | null {
    return null;
  }

  onSearch(event: any) {
    const inputElement = event.target as HTMLInputElement;
    const value = inputElement.value;
    this.fetchBlogPosts(this.blogSlug!!, {
      q: value,
      size: 10,
    }, result => {
      this.blogPosts = result
    })
  }

  onPageChanged(params: IParams) {

  }
}
